import json, sys
d = json.load(sys.stdin)
# Find all string values containing file paths
def find_paths(obj, prefix=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            find_paths(v, f'{prefix}.{k}')
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            find_paths(v, f'{prefix}[{i}]')
    elif isinstance(obj, str) and ('/' in obj or '.md' in obj or '.ts' in obj):
        if 'PAI' in obj or 'CLAUDE' in obj or 'MEMORY' in obj or 'STEERING' in obj:
            print(f'{prefix}: {obj}')
find_paths(d)
